    ".rch-c{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--trait)}.rch-c input{flex:1;min-width:0;border:0;background:none;color:var(--texte);font:inherit;font-size:18px;outline:none;min-height:40px}" +
    ".rch-x{min-height:44px;padding:0 12px;border:1px solid var(--trait);border-radius:6px;background:var(--fond-2);color:var(--texte);font:inherit;font-size:14px;cursor:pointer}" +
    ".rch-l{overflow-y:auto;padding:6px 0}.rch-g{padding:10px 16px 4px;font-size:12px;font-weight:600;color:var(--texte-3)}" +
    ".rch-r{display:block;padding:8px 16px;text-decoration:none;color:var(--texte);border-left:3px solid transparent}.rch-r b{font-weight:600}.rch-r small{display:block;font-size:12px;color:var(--texte-3)}.rch-r span{display:block;font-size:13px;color:var(--texte-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}" +
    ".rch-r[aria-selected=true]{background:var(--fond-2);border-left-color:var(--or)}.rch-r mark{background:var(--surl-fond);color:var(--surl-texte);padding:0 1px}" +
    ".rch-v{padding:24px 16px;color:var(--texte-2);font-size:15px}.rch-p{padding:8px 16px;border-top:1px solid var(--trait);font-size:12px;color:var(--texte-3)}" +
    "@media (max-width:760px){.rch{padding:0}.rch-b{max-height:none;height:100%;border-radius:0}}";
  document.head.appendChild(css);
  var box = document.createElement("div"); box.className = "rch"; box.hidden = true;
  box.innerHTML = '<div class="rch-b" role="dialog" aria-modal="true" aria-label="Rechercher"><div class="rch-c"><svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="7" cy="7" r="5"/><path d="M11 11l4 4"/></svg>' +
    '<input type="search" id="rch-i" placeholder="Une notion, une date, un nom" aria-label="Rechercher" aria-controls="rch-l" autocomplete="off"><button type="button" class="rch-x">Fermer</button></div><div class="rch-l" id="rch-l" role="listbox" aria-label="Résultats"></div>' +
    '<p class="rch-p">Maquette : index limité aux thèmes, aux notions de H4 et G5, aux dates et personnages de H4.</p></div>';
  document.body.appendChild(box);
  var inp = box.querySelector("input"), list = box.querySelector(".rch-l"), sel = 0, res = [], retour = null;
  function esc(s) { return s.replace(/[&<>]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]; }); }
  function surl(t, q) { var p = plat(t), i = q ? p.indexOf(q) : -1; return i < 0 ? esc(t) : esc(t.slice(0, i)) + "<mark>" + esc(t.slice(i, i + q.length)) + "</mark>" + esc(t.slice(i + q.length)); }
  function rendre() {
    var q = plat(inp.value.trim());
    if (q.length < 2) { list.innerHTML = '<p class="rch-v">Essaie « simonie », « Canossa », « Schengen », « Øresund » ou « Hugues Capet ».</p>'; res = []; return; }
    res = IDX.filter(function (e) { return e.p.indexOf(q) >= 0; }).sort(function (a, b) { return (b.pt.indexOf(q) === 0) - (a.pt.indexOf(q) === 0) || (a.pt.indexOf(q) < 0) - (b.pt.indexOf(q) < 0); });
    if (!res.length) { list.innerHTML = '<p class="rch-v">Aucun résultat pour « ' + esc(inp.value) + ' ». Vérifie l’orthographe ou cherche un mot plus court.</p>'; return; }
    var h = "", n = 0, parK = {};
    res.forEach(function (e) { (parK[e.k] = parK[e.k] || []).push(e); });
    res = [];
    ORDRE.forEach(function (k) { if (!parK[k]) return; h += '<div class="rch-g">' + k + ' (' + parK[k].length + ')</div>'; parK[k].slice(0, 6).forEach(function (e) { res.push(e); h += '<a class="rch-r" role="option" id="rch-' + n + '" href="' + e.u + '" aria-selected="' + (n === sel) + '"><b>' + surl(e.t, q) + '</b><small>' + esc(e.s) + '</small>' + (e.d ? '<span>' + surl(e.d, q) + '</span>' : '') + '</a>'; n++; }); });
    list.innerHTML = h; if (sel >= res.length) sel = 0; maj();
  }
  function maj() { list.querySelectorAll(".rch-r").forEach(function (a, i) { a.setAttribute("aria-selected", i === sel); if (i === sel) { inp.setAttribute("aria-activedescendant", a.id); a.scrollIntoView({ block: "nearest" }); } }); }
  function ouvrir() { retour = document.activeElement; box.hidden = false; inp.value = ""; sel = 0; rendre(); inp.focus(); }
